    directoryRow.appendChild(remoteDirectory);
    button(directoryRow, "选择路径", () => this.chooseRemoteDirectory(readRemote(), remoteDirectory));
    qb.createEl("p", {
      text: "在 qBittorrent 工具 → 选项 → Web UI 中启用服务，自行设置用户名和密码，然后填写到这里。",
      cls: "al-muted",
    });
    const player = section("播放器");
